      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "PLZ",
      "vorgabe": "Die korrekte Postleitzahl des Wohnorts muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Wohnort",
      "vorgabe": "Der vollständige Wohnort (Ort) muss angegeben werden.",
